function filterSkills(e){document.querySelectorAll(".skills-tab-btn").forEach(t=>{t.getAttribute("data-skill-filter")===e?t.classList.add("active"):t.classList.remove("active")}),document.querySelectorAll(".skill-tag").forEach(t=>{const s=t.getAttribute("data-type");e==="all"||s===e?(t.style.display="flex",t.style.animation="fadeIn 0.3s ease forwards"):t.style.display="none"})}function filterProjects(e){document.querySelectorAll(".filter-btn").forEach(t=>{t.getAttribute("data-project-filter")===e?t.classList.add("active"):t.classList.remove("active")}),document.querySelectorAll(".project-card").forEach(t=>{const s=t.getAttribute("data-category"),c=s?s.split(/\s+/):[];e==="all"||c.includes(e)?(t.style.display="flex",t.style.animation="fadeIn 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards"):t.style.display="none"})}document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".skills-tab-btn").forEach(l=>{l.addEventListener("click",()=>{const t=l.getAttribute("data-skill-filter");t&&filterSkills(t)})}),document.querySelectorAll(".filter-btn").forEach(l=>{l.addEventListener("click",()=>{const t=l.getAttribute("data-project-filter");t&&filterProjects(t)})})}),window.filterSkills=filterSkills,window.filterProjects=filterProjects;
